161: func topLevelEntries(root string, maxEntries int) ([]string, error) {
162: 	entries, err := os.ReadDir(root)
163: 	if err != nil {
164: 		return nil, err
165: 	}
166: 	results := make([]string, 0, len(entries))
167: 	for _, entry := range entries {
168: 		if isIgnoredRepoDir(entry.Name()) {
169: 			continue
170: 		}
171: 		name := entry.Name()
172: 		if entry.IsDir() {
173: 			name += "/"
174: 		}
175: 		results = append(results, name)
176: 	}
177: 	sort.Strings(results)
178: 	if len(results) > maxEntries {
179: 		results = results[:maxEntries]
180: 	}
181: 	return results, nil
182: }
