215: func gitSummary(root string) (branch string, dirty bool, staged bool) {
216: 	branch = strings.TrimSpace(runGit(root, "rev-parse", "--abbrev-ref", "HEAD"))
217: 	status := runGit(root, "status", "--porcelain")
218: 	if strings.TrimSpace(status) == "" {
219: 		return branch, false, false
220: 	}
221: 	for _, line := range strings.Split(strings.TrimRight(status, "\n"), "\n") {
222: 		if len(line) < 2 {
223: 			continue
224: 		}
225: 		if line[0] != ' ' && line[0] != '?' {
226: 			staged = true
227: 		}
228: 		if line[1] != ' ' || strings.HasPrefix(line, "??") {
229: 			dirty = true
230: 		}
231: 	}
232: 	return branch, dirty, staged
233: }
