235: func runGit(root string, args ...string) string {
236: 	cmd := exec.Command("git", args...)
237: 	cmd.Dir = root
238: 	out, err := cmd.Output()
239: 	if err != nil {
240: 		return ""
241: 	}
242: 	return string(out)
243: }
